 if(t.dataset.powerField){const r=state.power.rows.find(r=>r.id===t.closest('[data-power-row]')?.dataset.powerRow);if(!r)return true;const field=t.dataset.powerField;r[field]=t.value;if(field==='equipment')applyEquipment(r);if(field==='mode'&&r.mode!=='curve')r.equipment='custom';if(redraw&&t.tagName==='SELECT')renderPower();if(field==='name'){const card=t.closest('[data-power-row]');if(card)card.querySelector('.rowtitle strong').textContent=powerName(r,state.power.rows.indexOf(r));state.power.rows.forEach((row,i)=>{const select=$('powerRows').querySelector('[data-power-row="'+row.id+'"] [data-power-field="parent"]');if(select)select.innerHTML=powerParents(i,row.parent);});}refreshPower();saveLocal();return true;}
