 svg.setAttribute('viewBox',`0 0 ${w} ${h}`);const units=s.graphMode==='absolute'?'dBmV':'dB',title=s.graphMode==='absolute'?'Predicted signal level':s.graphMode==='loss'?'Total path loss':'Normalized path response';
