function validateImport(s){
 const record=x=>x&&typeof x==='object'&&!Array.isArray(x);
 const scalar=(x,label,max=30000)=>{if(typeof x!=='string'&&typeof x!=='number')throw Error('Invalid '+label+'.');if(typeof x==='number'&&!Number.isFinite(x))throw Error('Invalid '+label+'.');if(String(x).length>max)throw Error(label+' is too long.');};
 if(!record(s)||!record(s.setup)||!Array.isArray(s.rows))throw Error('Not a supported calculator project.');
 for(const key of ['lowF','highF','lowLevel','highLevel','liveMax','temperature','viewStart','viewEnd','referenceF'])if(s.setup[key]!==undefined)scalar(s.setup[key],key,100);
 for(const [key,values] of Object.entries({launchMode:['sqrt','linear','table'],basis:['nominal','max'],graphMode:['absolute','normalized','loss']}))if(s.setup[key]!==undefined&&!values.includes(s.setup[key]))throw Error('Invalid '+key+'.');
 for(const key of ['extendLaunch'])if(s.setup[key]!==undefined&&typeof s.setup[key]!=='boolean')throw Error('Invalid '+key+'.');
 if(s.setup.launchTable!==undefined)scalar(s.setup.launchTable,'launch table');
 if(typeof LaunchSource!=='undefined')LaunchSource.validate(s.setup);
 if(s.equipmentSetup!==undefined){if(typeof EquipmentSetup==='undefined')throw Error('Equipment setup module unavailable.');EquipmentSetup.validate(s.equipmentSetup);}
 for(const row of s.rows){if(!record(row))throw Error('Invalid route row.');for(const key of ['name','length','slack','cable','device','parent','customLoss','customCable','activeGainTable','activeGain','activeMinF','activeMaxF','targetLow','targetHigh','reserve','outputLimitLow','outputLimitHigh','gainLow','gainHigh','gainLowF','gainHighF','outputLoss','measureIn','measureOut','measureInTP','measureOutTP','measureF'])if(row[key]!==undefined)scalar(row[key],'route '+key);if(row.activeMode!==undefined&&!['anchors','table','flat'].includes(row.activeMode))throw Error('Invalid active gain mode.');if(row.terminal!==undefined&&typeof row.terminal!=='boolean')throw Error('Invalid terminal setting.');}
 if(s.routeTools!==undefined){if(!record(s.routeTools))throw Error('Invalid route tools.');for(const key of ['frequency','endpoint','start','direction','distance','lead','setVF','actualVF'])if(s.routeTools[key]!==undefined)scalar(s.routeTools[key],key,100);if(s.routeTools.direction!==undefined&&!['forward','reverse'].includes(s.routeTools.direction))throw Error('Invalid TDR direction.');if(s.routeTools.vfEnabled!==undefined&&typeof s.routeTools.vfEnabled!=='boolean')throw Error('Invalid TDR VF setting.');}
 // 0.12 additions remain optional for schema-1 jobs.
 for(const k of ['launchCoupling','launchCouplingChoice','launchTpReference','launchTpTolerance'])if(s.setup[k]!==undefined&&s.setup[k]!==null)scalar(s.setup[k],k,300);
 if(s.setup.launchTestPoint!==undefined&&typeof s.setup.launchTestPoint!=='boolean')throw Error('Invalid launch test-point setting.');
 if(s.job!==undefined){if(!record(s.job))throw Error('Invalid named job metadata.');for(const [k,v] of Object.entries(s.job)){if(k==='sample'){if(typeof v!=='boolean')throw Error('Invalid sample flag.');}else scalar(v,'named job '+k,({workOrder:200,address:1000,symptom:2000,startTime:40,endTime:40,weather:1000,resolution:8000,partsUsed:4000})[k]||300);}}
 for(const row of s.rows){
  if(row.toolFrequency!==undefined)scalar(row.toolFrequency,'point comparison frequency',100);
  if(row.asBuiltNote!==undefined)scalar(row.asBuiltNote,'as-built / map variance note',2000);
  if(row.meters!==undefined){if(!record(row.meters)||Object.keys(row.meters).length>32)throw Error('Invalid point meter records.');for(const m of Object.values(row.meters)){if(!record(m))throw Error('Invalid point meter.');for(const [k,v] of Object.entries(m)){if(k==='testPoint'){if(typeof v!=='boolean')throw Error('Invalid meter test-point setting.');}else if(v!==null)scalar(v,'meter '+k,300);}}}
  if(row.drop!==undefined){if(!record(row.drop))throw Error('Invalid drop.');for(const [k,v] of Object.entries(row.drop))scalar(v,'drop '+k,k==='customCable'||k==='customLoss'?30000:300);}
 }
 if(s.power?.whatIf!==undefined){if(!record(s.power.whatIf))throw Error('Invalid power trial.');for(const [k,v] of Object.entries(s.power.whatIf))scalar(v,'power trial '+k,300);}
 if(s.sweepSetup!==undefined){if(typeof SweepSetup==='undefined')throw Error('Sweep setup module unavailable.');SweepSetup.validate(s.sweepSetup);}
 if(s.fieldWork!==undefined)FieldWork.validate(s.fieldWork);
 if(s.fieldReferences!==undefined)FieldReference.validate(s.fieldReferences);
 if(s.evidence!==undefined)EvidenceCore.validateEvidence(s.evidence);
 if(s.node!==undefined)validateNode(s.node);
 if(s.frequency!==undefined){if(typeof validateFrequency!=='function')throw Error('Frequency calculator unavailable.');validateFrequency(s.frequency);}
 if(s.project!==undefined){if(!record(s.project))throw Error('Invalid project data.');if(typeof validateProject==='function')validateProject(s.project);else for(const key of ['profiles','forward','returns','punch','dsim'])if(s.project[key]!==undefined&&(!Array.isArray(s.project[key])||s.project[key].length>2000))throw Error('Invalid project '+key+'.');}
 if(s.power!==undefined){if(!record(s.power)||!Array.isArray(s.power.rows))throw Error('Invalid power plan.');for(const key of ['supplyVoltage','supplyRating','temperatureF','resistanceAlpha'])if(s.power[key]!==undefined)scalar(s.power[key],key,100);for(const row of s.power.rows){if(!record(row))throw Error('Invalid power row.');for(const key of ['name','length','cable','dcRate','extraR','equipment','load','pf','minV','parent'])if(row[key]!==undefined)scalar(row[key],'power '+key);if(row.mode!==undefined&&!['curve','watts','va','amps'].includes(row.mode))throw Error('Invalid power load mode.');}}
}
function loadState(s,render=true,validateOnly=false){validateImport(s);if(!s||s.version!==1||!Array.isArray(s.rows)||!s.setup||s.rows.length>200)throw Error('Not a supported calculator route.');const ids=new Set();for(const r of s.rows){if(!r||typeof r.id!=='string'||!/^r\d+$/.test(r.id)||!Number.isSafeInteger(Number(r.id.slice(1)))||ids.has(r.id)||typeof r.device!=='string'||typeof r.parent!=='string')throw Error('Invalid route rows.');ids.add(r.id);}let power=freshPower();if(s.power!==undefined){if(!s.power||!Array.isArray(s.power.rows)||s.power.rows.length>200)throw Error('Invalid power plan.');const powerIds=new Set();for(const r of s.power.rows){if(!r||typeof r.id!=='string'||!/^p\d+$/.test(r.id)||!Number.isSafeInteger(Number(r.id.slice(1)))||powerIds.has(r.id)||typeof r.parent!=='string')throw Error('Invalid power rows.');powerIds.add(r.id);}power={...freshPower(),...s.power,rows:s.power.rows.map(r=>({...freshPowerRow(r.id),...r}))};}const nextState={...s,version:1,example:!!s.example,setup:{...defaultSetup,...s.setup},rows:s.rows.map(r=>({...r,family:device(r.device)?.family,passiveType:passiveType(device(r.device))})),power,...(s.routeTools?{routeTools:s.routeTools}:{}),...(s.node?{node:s.node}:{}),...(s.evidence?{evidence:s.evidence}:{}),...(s.project?{project:s.project}:{}),...(s.frequency?{frequency:{...freshFrequency(),...s.frequency,points:s.frequency.points||{}}}:{})};delete nextState.evidenceFiles;if(validateOnly)return nextState;state=nextState;powerSerial=Math.max(0,...power.rows.map(r=>Number(r.id.slice(1))))+1;serial=Math.max(0,...s.rows.map(r=>Number(r.id.slice(1))))+1;selected=new Set(['source',...state.rows.map(r=>{const p=HFC.portsFor(device(r.device),r);return r.id+'::'+(p.find(p=>p.role==='tap')?.id||p[0]?.id)})]);if(render)renderAll();}
async function openProjectText(text,confirmed=false){
 if(typeof evidenceIsBusy==='function'&&evidenceIsBusy())throw Error('Finish the current evidence operation first.');
 let candidate=JSON.parse(text);
 loadState(candidate,false,true);
 if(candidate.evidence?.length||candidate.evidenceFiles!==undefined)candidate=await evidencePrepareImport(candidate);
 if(typeof JobsUI!=='undefined'&&!JobsUI.beforeProjectOpen({confirmed}))return false;
 loadState(candidate);return true;
}
