$('csv').onclick=()=>{const freq=tableFreq(),evals=freq.map(evaluate),quote=csvCell;const rows=[['Predicted RF levels, not measured'],...jobContextCsvRows(),['Passive basis',state.setup.basis,'Available spectrum MHz',state.setup.liveMax],['Low anchor MHz',state.setup.lowF,'Low level dBmV',state.setup.lowLevel],['High anchor MHz',state.setup.highF,'High level dBmV',state.setup.highLevel],['Launch mode',state.setup.launchMode,'Slope extension',state.setup.extendLaunch],['Cable temperature F',state.setup.temperature],['Scope','Missing data is blank; passives/cables are never extrapolated. Values above available spectrum are planning predictions.'],['Point / output',...freq.map(f=>f+' MHz dBmV'),'As-built / map variance'],...allTraces().filter(t=>t.role!=='input').map(t=>[t.label,...evals.map(r=>{const v=val(r,t.key);return v===null?'':v.toFixed(4)}),t.row?.asBuiltNote||''])];download('NightSweep_1.8_Alpha_RF_Levels.csv',rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv');};
