$('powerJunction').onclick=()=>{if(state.power.rows.length>=200){$('message').textContent='Maximum 200 power rows.';return;}state.power.rows.push(freshPowerRow(undefined,true));renderPower();refreshPower();saveLocal();};
$('powerRows').addEventListener('click',e=>{const id=e.target.dataset.powerDelete;if(!id)return;state.power.rows=state.power.rows.filter(r=>r.id!==id);renderPower();refreshPower();saveLocal();});
$('powerCSV').onclick=()=>{const r=HFC.powerRun(state.power,catalog),quote=csvCell,rows=[['CATV power-supply OUTPUT load — scalar RMS planning estimate'],...jobContextCsvRows(),['Supply voltage V',state.power.supplyVoltage,'Supply rating A',state.power.supplyRating],['Output current A',r.supplyCurrent,'Loading percent',r.loading,'Headroom A',r.headroom],['Cable/contact resistive loss W',r.wireWatts,'Lowest equipment voltage V',r.minVoltage],['Point','Power parent','Cable feet','Cable','Equipment model','Mode','Input load','Input power factor','Voltage V','Device current A','Section current A','Section drop V','Section loss W','Equipment source','Status'],...state.power.rows.map((p,i)=>{const x=(r.rows||[]).find(x=>x.id===p.id)||{},e=powerEquipment(p.equipment);return [powerName(p,i),p.parent,p.length,p.cable,e?.label||'Custom',p.mode,p.load,p.mode==='watts'?p.pf:'',x.voltage,x.deviceCurrent,x.sectionCurrent,x.drop,x.wireWatts,e?.source_url||'',x.warning||''];}),['Calculation status',r.error||(r.warnings||[]).join(' | ')||'Complete within planning model'],['Scope','Scalar RMS estimate; actual quasi-square-wave behavior and power factor can differ. Verify power-passing and equipment configuration.'],['Power cable temperature F',state.power.temperatureF],['Resistance coefficient per C',state.power.resistanceAlpha],['Cable resistance','Built-in nominal loop resistance adjusted from 68 F using selected coefficient. Custom loop/contact resistance used as entered at actual temperature. Equipment load temperature dependence is not modeled.'],['Current scope','CATV coax output current, not utility mains current.']];download('NightSweep_1.8_Alpha_Power_Load.csv',rows.map(x=>x.map(quote).join(',')).join('\r\n'),'text/csv');};
$('print').onclick=()=>{if(window.NightSweepAndroid?.printReport)window.NightSweepAndroid.printReport();else window.print();};$('tapsOnly').onchange=refreshResults;
updateCatalogFamilies();
$('catalogFamily').onchange=renderCatalog;$('catalogSearch').oninput=renderCatalog;if($('catalogCategory'))$('catalogCategory').onchange=()=>{updateCatalogFamilies();renderCatalog();};
$('catalogSummary').textContent=`Equipment, gain and loss data · ${catalog.devices.filter(d=>!d.custom&&d.id!=='none'&&!d.retired).length} RF models · ${catalog.cables.length} cables · ${(catalog.nodeProfiles||[]).length} nodes · ${(catalog.powerEquipment||[]).filter(e=>!e.retired).length} power loads`;

const screenCopy={route:['RF PLANNING','Trace the signal.','Follow cable distance, losses and amplifier gain.'],sweep:['EXPECTED RESPONSE','Read the sweep.','Predicted levels and tilt at every output.'],power:['CATV COAX POWER','Know the load.','Follow shared trunks and branches from the supply.'],parts:['FIELD REFERENCE','Find your equipment.','Active operating gain, passive losses and source conditions.'],projects:['FIELD PROJECTS','Keep the job together.','Node profiles, ONX evidence, forward and return checks, and closeout.'],help:['NIGHTSWEEP','Built for the field.','How to use the calculators and interpret their limits.']};
function showTab(tab){
 if(!screenCopy[tab])tab='route';document.querySelectorAll('[data-screen]').forEach(el=>el.hidden=el.dataset.screen!==tab);
 document.querySelectorAll('[data-tab]').forEach(el=>{const active=el.dataset.tab===tab;el.classList.toggle('active',active);active?el.setAttribute('aria-current','page'):el.removeAttribute('aria-current');});
 const copy=screenCopy[tab];$('screenTitle').innerHTML=`<span class="eyebrow">${copy[0]}</span><h2>${copy[1]}</h2><p>${copy[2]}</p>`;
 document.querySelector('.filemenu').open=false;window.scrollTo({top:0,behavior:'instant'});if(tab==='sweep'){if(typeof renderFrequency==='function')renderFrequency();requestAnimationFrame(drawChart);}
}
document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>showTab(el.dataset.tab));
$('helpButton').onclick=()=>showTab('help');
document.querySelector('.filelabel').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('load').click();}});
document.addEventListener('click',e=>{const menu=document.querySelector('.filemenu');if(menu.open&&!menu.contains(e.target))menu.open=false;});
window.NightSweep={openProject:async text=>{if(await openProjectText(text))$('message').textContent='Project opened.';},onNativeStatus:message=>{$('message').textContent=String(message);},showTab};

if(typeof initProjects==='function')initProjects();if(typeof initFrequency==='function')initFrequency();initial();if(typeof initNodes==='function')initNodes();renderAll();if(typeof initEvidence==='function')initEvidence();renderCatalog();new ResizeObserver(()=>drawChart()).observe($('plot'));

/* Expand record details only while producing a report. */
let nightSweepPrintDetails=null;
window.NightSweep=window.NightSweep||{};
window.NightSweep.preparePrint=()=>{if(nightSweepPrintDetails)return;nightSweepPrintDetails=[...document.querySelectorAll('details')].map(el=>({el,open:el.open}));nightSweepPrintDetails.forEach(x=>x.el.open=true);drawChart();};
window.NightSweep.restorePrint=()=>{if(!nightSweepPrintDetails)return;nightSweepPrintDetails.forEach(x=>x.el.open=x.open);nightSweepPrintDetails=null;};
window.NightSweep.onNativeStatus=message=>{$('message').textContent=String(message);};
window.addEventListener('beforeprint',window.NightSweep.preparePrint);
window.addEventListener('afterprint',window.NightSweep.restorePrint);
